mapper.select:
SELECT p.id AS jobId, p.title, p.status, p.city_code AS cityCode, p.city_name AS cityName, p.salary_min_amount AS salaryMinAmount, p.salary_max_amount AS salaryMaxAmount, p.salary_currency AS salaryCurrency, p.salary_period AS salaryPeriod, p.salary_months AS salaryMonths, p.is_salary_negotiable AS salaryNegotiable, p.salary_raw_text AS salaryRawText, p.total_hc AS totalHc, p.reserved_hc AS reservedHc, p.confirmed_hc AS confirmedHc, (p.total_hc - p.reserved_hc - p.confirmed_hc) AS availableHc, pf.job_type AS jobType, pf.core_skills AS skillTagsRaw, p.version, p.published_at AS publishedAt, p.updated_at AS updatedAt, p.created_by AS createdBy FROM job_post p LEFT JOIN job_profile pf ON pf.job_id = p.id WHERE p.deleted_at IS NULL AND p.company_id = #{q.companyId}
AND p.status = #{q.status}
ORDER BY p.updated_at DESC, p.id DESC

mapper.sql:
FROM job_post p
LEFT JOIN job_profile pf ON pf.job_id = p.id AND pf.company_id = p.company_id
WHERE p.deleted_at IS NULL AND p.status = 'PUBLISHED'


    AND (

        p.title LIKE CONCAT('%', #{kw}, '%') ESCAPE '='

    )



    AND (p.title LIKE CONCAT('%', #{q.keyword}, '%') ESCAPE '='
         OR p.jd_summary LIKE CONCAT('%', #{q.keyword}, '%') ESCAPE '=')



    AND p.industry_group_code = #{q.industryGroupCode}


    AND p.industry_code = #{q.industryCode}


    AND p.city_code = #{q.cityCode}



    AND (
        p.is_salary_negotiable = 1
        OR (
            1 = 1
            AND p.salary_max_amount >= #{q.salaryMin}
            AND p.salary_min_amount <= #{q.salaryMax}
        )
    )



    AND p.min_experience_years <= #{q.experienceMax}



    AND p.education_requirement IN

        #{code}




    AND pf.job_type = #{q.jobType}



    AND p.company_id IN (SELECT id FROM hr_company WHERE name LIKE CONCAT('%', #{q.company}, '%'))



    AND (

        JSON_CONTAINS(JSON_EXTRACT(pf.core_skills, '$[*].name'), JSON_QUOTE(#{skill}))

    )
